<?php declare(strict_types=1); $title = 'Venta #' . $sale['id']; ?>
<section><div class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><a href="<?= e($baseUrl) ?>/ventas" class="text-sm font-semibold text-emerald-800">← Historial de ventas</a><h1 class="mt-3 text-3xl font-bold text-slate-900">Comprobante interno #<?= e($sale['id']) ?></h1><p class="mt-2 text-sm text-slate-600"><?= e(date('d/m/Y H:i', strtotime($sale['fecha']))) ?> · Atendió <?= e($sale['usuario']) ?></p></div><?php if ($sale['estado']==='confirmada' && can('ventas.anular')): ?><form method="post" action="<?= e($baseUrl) ?>/ventas/anular" onsubmit="return confirm('¿Anular esta venta y restaurar las existencias de sus lotes?');"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($sale['id']) ?>"><button class="rounded-lg border border-red-300 px-4 py-3 text-sm font-semibold text-red-700">Anular venta</button></form><?php endif; ?></div>
<?php if ($success): ?><div role="status" class="mb-5 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-900"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div role="alert" class="mb-5 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800"><?= e($error) ?></div><?php endif; ?>
