<div class="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200 text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-600"><tr><?php foreach (['Producto', 'Lote', 'Vencimiento', 'Cantidad', 'Precio unitario', 'Descuento unitario', 'Subtotal'] as $label): ?><th class="px-4 py-3"><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($items as $item): ?><tr><td class="px-4 py-3"><strong><?= e($item['producto']) ?></strong><div class="text-xs text-slate-500"><?= e($item['codigo']) ?></div></td><td class="px-4 py-3"><?= e($item['codigo_lote']) ?></td><td class="px-4 py-3"><?= e($item['fecha_vencimiento'] ? date('d/m/Y', strtotime($item['fecha_vencimiento'])) : '—') ?></td><td class="px-4 py-3"><?= e(number_format((float)$item['cantidad'], 3)) ?> <?= e($item['unidad_medida']) ?></td><td class="px-4 py-3">S/ <?= e(number_format((float)$item['precio_unitario'], 2)) ?></td><td class="px-4 py-3">S/ <?= e(number_format((float)$item['descuento_unitario'], 2)) ?></td><td class="px-4 py-3">S/ <?= e(number_format((float)$item['subtotal'], 2)) ?></td></tr><?php endforeach; ?><tr class="bg-slate-50 font-bold"><td colspan="6" class="px-4 py-4 text-right">TOTAL</td><td class="px-4 py-4">S/ <?= e(number_format((float)$sale['total'], 2)) ?></td></tr></tbody></table></div></section>
